Set.Payload:
{
  "state": "{escapeJSON(flow.userPrompt)}",
  "model": "jev-latest",
  "questions": {
    "category": {
      "type": "choice",
      "instructions": "Classify the user intent into exactly one category: coding, deep_reasoning, simple, general",
      "criteria": {
        "coding": "Programming, software engineering, writing/debugging/refactoring code, SQL queries, regex, API development",
        "deep_reasoning": "Complex analysis, system architecture trade-offs, multi-step planning, root cause evaluation, benchmarking",
        "simple": "Short greetings, factual trivia, definitions, quick lookups, basic single-sentence questions",
        "general": "Open-ended writing, summarization, general discussion not requiring specialized code or deep architectural analysis"
      }
    }
  }
}
